WITH RecentSuppliers AS (SELECT * FROM suppliers WHERE city != 'New York' AND LOWER(supplier_name) LIKE '%aci%'), summary AS (SELECT city, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM RecentSuppliers GROUP BY city, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) SELECT city, rating_bucket FROM summary ORDER BY rating_bucket DESC, city LIMIT 1
